-- Sales & Business Analysis SQL Project


CREATE DATABASE IF NOT EXISTS SalesBusinessAnalysis;
USE SalesBusinessAnalysis;

DROP TABLE IF EXISTS sales_analysis;

CREATE TABLE sales_analysis (
    RowID INT NOT NULL PRIMARY KEY,
    OrderID VARCHAR(30) NOT NULL,
    OrderDate DATE NOT NULL,
    ShipDate DATE NOT NULL,
    ShipMode VARCHAR(50) NOT NULL,
    CustomerID VARCHAR(20) NOT NULL,
    CustomerName VARCHAR(100) NOT NULL,
    Segment VARCHAR(50) NOT NULL,
    Country VARCHAR(50) NOT NULL,
    City VARCHAR(100) NOT NULL,
    State VARCHAR(100) NOT NULL,
    PostalCode VARCHAR(20) NOT NULL,
    Region VARCHAR(50) NOT NULL,
    ProductID VARCHAR(30) NOT NULL,
    Category VARCHAR(50) NOT NULL,
    SubCategory VARCHAR(50) NOT NULL,
    ProductName VARCHAR(255) NOT NULL,
    Sales DECIMAL(12,2) NOT NULL,
    Quantity INT NOT NULL,
    Discount DECIMAL(5,2) NOT NULL,
    Profit DECIMAL(12,2) NOT NULL
);
























-- =========================================================
-- BUSINESS ANALYSIS QUERIES
-- =========================================================

-- 1. Validate the imported data
SELECT COUNT(*) AS total_rows FROM sales_analysis;

-- 2. Executive KPIs
SELECT
    COUNT(DISTINCT OrderID) AS total_orders,
    COUNT(DISTINCT CustomerID) AS total_customers,
    SUM(Quantity) AS units_sold,
    ROUND(SUM(Sales), 2) AS total_sales,
    ROUND(SUM(Profit), 2) AS total_profit,
    ROUND(100 * SUM(Profit) / NULLIF(SUM(Sales), 0), 2) AS profit_margin_pct
FROM sales_analysis;

-- 3. Sales and profit by category
SELECT Category,
       ROUND(SUM(Sales), 2) AS total_sales,
       ROUND(SUM(Profit), 2) AS total_profit,
       SUM(Quantity) AS units_sold
FROM sales_analysis
GROUP BY Category
ORDER BY total_sales DESC;

-- 4. Sales and profit by region
SELECT Region,
       ROUND(SUM(Sales), 2) AS total_sales,
       ROUND(SUM(Profit), 2) AS total_profit,
       ROUND(100 * SUM(Profit) / NULLIF(SUM(Sales), 0), 2) AS profit_margin_pct
FROM sales_analysis
GROUP BY Region
ORDER BY total_sales DESC;

-- 5. Monthly sales and profit trend
SELECT DATE_FORMAT(OrderDate, '%Y-%m') AS sales_month,
       ROUND(SUM(Sales), 2) AS total_sales,
       ROUND(SUM(Profit), 2) AS total_profit,
       COUNT(DISTINCT OrderID) AS total_orders
FROM sales_analysis
GROUP BY DATE_FORMAT(OrderDate, '%Y-%m')
ORDER BY sales_month;

-- 6. Top 10 products by sales
SELECT ProductID, ProductName,
       SUM(Quantity) AS units_sold,
       ROUND(SUM(Sales), 2) AS total_sales,
       ROUND(SUM(Profit), 2) AS total_profit
FROM sales_analysis
GROUP BY ProductID, ProductName
ORDER BY total_sales DESC
LIMIT 10;

-- 7. Top 10 customers by sales
SELECT CustomerID, CustomerName,
       COUNT(DISTINCT OrderID) AS order_count,
       ROUND(SUM(Sales), 2) AS total_sales,
       ROUND(SUM(Profit), 2) AS total_profit
FROM sales_analysis
GROUP BY CustomerID, CustomerName
ORDER BY total_sales DESC
LIMIT 10;

-- 8. Sub-categories making a loss
SELECT Category, SubCategory,
       ROUND(SUM(Sales), 2) AS total_sales,
       ROUND(SUM(Profit), 2) AS total_profit
FROM sales_analysis
GROUP BY Category, SubCategory
HAVING SUM(Profit) < 0
ORDER BY total_profit ASC;

-- 9. Discount band vs profitability
SELECT
    CASE
        WHEN Discount = 0 THEN '0% - No discount'
        WHEN Discount <= 0.10 THEN '1-10%'
        WHEN Discount <= 0.20 THEN '11-20%'
        WHEN Discount <= 0.30 THEN '21-30%'
        ELSE 'Above 30%'
    END AS discount_band,
    COUNT(*) AS order_lines,
    ROUND(SUM(Sales), 2) AS total_sales,
    ROUND(SUM(Profit), 2) AS total_profit,
    ROUND(100 * SUM(Profit) / NULLIF(SUM(Sales), 0), 2) AS profit_margin_pct
FROM sales_analysis
GROUP BY discount_band
ORDER BY MIN(Discount);

-- 10. Customer segment analysis
SELECT Segment,
       COUNT(DISTINCT CustomerID) AS customers,
       COUNT(DISTINCT OrderID) AS total_orders,
       ROUND(SUM(Sales), 2) AS total_sales,
       ROUND(SUM(Profit), 2) AS total_profit
FROM sales_analysis
GROUP BY Segment
ORDER BY total_sales DESC;

-- 11. Shipping performance
SELECT ShipMode,
       COUNT(DISTINCT OrderID) AS total_orders,
       ROUND(AVG(DATEDIFF(ShipDate, OrderDate)), 2) AS avg_shipping_days,
       ROUND(SUM(Sales), 2) AS total_sales
FROM sales_analysis
GROUP BY ShipMode
ORDER BY avg_shipping_days;

-- 12. Month-over-month sales growth 
WITH monthly_sales AS (
    SELECT DATE_FORMAT(OrderDate, '%Y-%m-01') AS sales_month,
           SUM(Sales) AS total_sales
    FROM sales_analysis
    GROUP BY DATE_FORMAT(OrderDate, '%Y-%m-01')
),
monthly_with_previous AS (
    SELECT sales_month, total_sales,
           LAG(total_sales) OVER (ORDER BY sales_month) AS previous_month_sales
    FROM monthly_sales
)
SELECT sales_month,
       ROUND(total_sales, 2) AS total_sales,
       ROUND(previous_month_sales, 2) AS previous_month_sales,
       ROUND(100 * (total_sales - previous_month_sales) /
             NULLIF(previous_month_sales, 0), 2) AS growth_pct
FROM monthly_with_previous
ORDER BY sales_month;

-- 13. Rank products by profit within each category 
WITH product_profit AS (
    SELECT Category, ProductID, ProductName,
           SUM(Profit) AS total_profit
    FROM sales_analysis
    GROUP BY Category, ProductID, ProductName
),
ranked_products AS (
    SELECT *,
           DENSE_RANK() OVER (PARTITION BY Category ORDER BY total_profit DESC) AS profit_rank
    FROM product_profit
)
SELECT Category, ProductID, ProductName,
       ROUND(total_profit, 2) AS total_profit, profit_rank
FROM ranked_products
WHERE profit_rank <= 3
ORDER BY Category, profit_rank;

-- 14. Data quality checks
SELECT
    SUM(OrderDate IS NULL) AS missing_order_dates,
    SUM(ShipDate IS NULL) AS missing_ship_dates,
    SUM(Sales < 0) AS negative_sales_rows,
    SUM(Quantity <= 0) AS invalid_quantity_rows
FROM sales_analysis;

